// uploads/checkbox/checkbox.component.spec.ts
try { (() => {
describe('IvuCheckboxComponent', () => {
  let component;
  let fixture;
  beforeEach(async () => {
    await TestBed.configureTestingModule({
      imports: [__ds_scope.IvuCheckboxComponent]
    }).compileComponents();
    fixture = TestBed.createComponent(__ds_scope.IvuCheckboxComponent);
    component = fixture.componentInstance;
    fixture.detectChanges();
  });
  it('should create', () => {
    expect(component).toBeTruthy();
  });
  describe('#onCheckboxClick', () => {
    it('should toggle checked to true when the checkbox is unchecked', () => {
      component.checked = false;
      fixture.detectChanges();
      fixture.nativeElement.querySelector('input[type="checkbox"]').click();
      expect(component.checked).toBe(true);
    });
    it('should toggle checked to false when the checkbox is checked', () => {
      component.checked = true;
      fixture.detectChanges();
      fixture.nativeElement.querySelector('input[type="checkbox"]').click();
      expect(component.checked).toBe(false);
    });
  });
  describe('#onLabelClick', () => {
    it('should toggle checked from false to true', () => {
      component.checked = false;
      component.label = 'Test';
      fixture.detectChanges();
      fixture.debugElement.query(By.css('.ivu-checkbox-label')).triggerEventHandler('click');
      expect(component.checked).toBe(true);
    });
  });
  describe('template', () => {
    it('should have a checkbox', () => {
      const checkbox = fixture.nativeElement.querySelector('input[type="checkbox"]');
      expect(checkbox).toBeTruthy();
    });
    it('should have an label if text was provided', () => {
      fixture.componentRef.setInput('label', 'Test');
      fixture.detectChanges();
      const label = fixture.debugElement.query(By.css('.ivu-checkbox-label'));
      expect(label).toBeTruthy();
    });
    it('should have a label with the provided text', () => {
      fixture.componentRef.setInput('label', 'Test');
      fixture.detectChanges();
      const label = fixture.debugElement.query(By.css('.ivu-checkbox-label'));
      expect(label.nativeElement.textContent).toContain('Test');
    });
  });
  describe('disabled', () => {
    it('should not be disabled by default', () => {
      const checkbox = fixture.nativeElement.querySelector('input[type="checkbox"]');
      expect(checkbox.disabled).toBe(false);
    });
    it('should be disabled when disabled is true', () => {
      fixture.componentRef.setInput('disabled', true);
      fixture.detectChanges();
      const checkbox = fixture.nativeElement.querySelector('input[type="checkbox"]');
      expect(checkbox.disabled).toBe(true);
    });
    it('should not toggle checked when disabled is true', () => {
      component.checked = false;
      component.disabled = true;
      fixture.detectChanges();
      component.onClick();
      expect(component.checked).toBe(false);
    });
  });
  describe('indeterminate', () => {
    it('should not be indeterminate by default', () => {
      expect(component.indeterminate).toBe(false);
    });
    it('should be indeterminate when indeterminate is true', () => {
      component.indeterminate = true;
      fixture.detectChanges();
      expect(component.indeterminate).toBe(true);
    });
    it('should toggle from intermediate to checked', () => {
      component.indeterminate = true;
      component.checked = true;
      fixture.detectChanges();
      component.onClick();
      expect(component.checked).toBe(true);
    });
    it('should not be affected by indeterminate when toggling from unchecked to checked', () => {
      component.indeterminate = true;
      component.checked = false;
      fixture.detectChanges();
      component.onClick();
      expect(component.checked).toBe(true);
    });
    it('should not be indeterminate after a click', () => {
      component.indeterminate = true;
      fixture.detectChanges();
      component.onClick();
      expect(component.indeterminate).toBe(false);
    });
    it('should emit an event when indeterminate toggles', () => {
      component.indeterminate = true;
      fixture.detectChanges();
      jest.spyOn(component.indeterminateChange, 'emit');
      component.onClick();
      expect(component.indeterminateChange.emit).toHaveBeenCalled();
    });
  });
});
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/checkbox/checkbox.component.spec.ts", error: String((e && e.message) || e) }); }

