// uploads/columnar-table/column-header/column-header.component.cy.ts
try { (() => {
describe(__ds_scope.IvuColumnHeaderComponent.name, () => {
  let mockTripInfo;
  let headerAttributeConfig;
  beforeEach(() => {
    mockTripInfo = __ds_scope.getTripInfo();
    headerAttributeConfig = __ds_scope.getHeaderAttributeConfig();
    cy.mount(__ds_scope.IvuColumnHeaderComponent, {
      componentProperties: {
        attribute: headerAttributeConfig[4],
        column: mockTripInfo[0],
        value: mockTripInfo[0].vehicle
      }
    });
  });
  it('should render column header', () => {
    cy.dataTestId('columnHeader').should('exist');
  });
  it('should render appropriate value in the column header when value is passed', () => {
    cy.dataTestId('columnHeader').should('contain.text', 'Gelenkus');
  });
  it(`should check if ellipsis is displayed when there is no enough space to render the 
    value in available width`, () => {
    cy.mount(`<div style="width:60px">
        <ivu-column-header [attribute]="attribute" [column]="column" [value]="value"></ivu-column-header>
        </div>`, {
      componentProperties: {
        attribute: headerAttributeConfig[4],
        column: mockTripInfo[0],
        value: mockTripInfo[0].vehicle
      },
      imports: [__ds_scope.IvuColumnHeaderComponent]
    });
    cy.dataTestId('columnHeader').should('contain.text', 'Gelenkus');
    cy.dataTestId('columnHeader').then($el => {
      const clientWidth = $el[0].clientWidth;
      const scrollWidth = $el[0].scrollWidth;
      expect(clientWidth).to.be.at.most(scrollWidth);
    });
  });
  it(`should check if provided template is rendered in column header when a template input property is passed`, () => {
    cy.mount(`<ng-template #sample>
        <span data-testid="customValue">Tricon</span>
      </ng-template>
      <ivu-column-header [attribute]="attribute" [column]="column" [value]="value" [template]="sample"></ivu-column-header>
    `, {
      componentProperties: {
        attribute: headerAttributeConfig[4],
        column: mockTripInfo[0],
        value: mockTripInfo[0].vehicle
      },
      imports: [__ds_scope.IvuColumnHeaderComponent, NgTemplateOutlet]
    });
    cy.dataTestId('customValue').should('exist').should('contain.text', 'Tricon');
  });
});
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/columnar-table/column-header/column-header.component.cy.ts", error: String((e && e.message) || e) }); }

