/**
 * Adds new row by applying ADD type of transaction on the service.
 *
 * @param {IvuTransactionService<TableData>} service
 * @param {TableData} rowData
 */
function addNewRow(service, rowData) {
  const transactionRecord = {
    newData: rowData
  };
  service.applyTransaction(__ds_scope.IvuTransactionType.ADD, [transactionRecord]);
}

/**
 * Removes a row by applying REMOVE type of transaction on the service.
 *
 * @param {IvuTransactionService<TableData>} service
 * @param {TableData} rowData
 */
function removeRow(service, rowData) {
  const transactionRecord = {
    oldData: rowData
  };
  service.applyTransaction(__ds_scope.IvuTransactionType.REMOVE, [transactionRecord]);
}

/**
 * Modifies a row by applying UPDATE type of transaction on the service.
 *
 * @param {IvuTransactionService<TableData>} service
 * @param {TableData} oldData
 * @param {TableData} newData
 */
function editRow(service, oldData, newData) {
  const transactionRecord = {
    oldData,
    newData
  };
  service.applyTransaction(__ds_scope.IvuTransactionType.UPDATE, [transactionRecord]);
}
