try { (() => {
describe('IvuDayButtonComponent', () => {
  beforeEach(() => {
    cy.mount(__ds_scope.IvuDayButtonComponent, {
      imports: [],
      providers: [__ds_scope.IvuDateTimePickerService]
    });
  });
  it('should display the correct date', () => {
    const testDate = new Date(2023, 3, 15); // April 15th, 2023
    cy.mount(__ds_scope.IvuDayButtonComponent, {
      componentProperties: {
        day: testDate
      },
      providers: [__ds_scope.IvuDateTimePickerService]
    });
    cy.get('[data-testid="time"]').should('contain.text', testDate.getDate().toString());
  });
  const today = new Date();
  const testCases = [{
    isSelected: true,
    isToday: true,
    isInCurrentMonth: true,
    description: 'Selected, Today, Current Month',
    date: new Date(today)
  }, {
    isSelected: true,
    isToday: false,
    isInCurrentMonth: true,
    description: 'Selected, Not Today, Current Month',
    date: new Date(today.getFullYear(), today.getMonth(), today.getDate() === 1 ? 2 : 1)
  }, {
    isSelected: false,
    isToday: true,
    isInCurrentMonth: true,
    description: 'Not Selected, Today, Current Month',
    date: new Date(today)
  }, {
    isSelected: false,
    isToday: false,
    isInCurrentMonth: false,
    description: 'Not Selected, Not Today, Not Current Month',
    date: new Date(today.getFullYear(), today.getMonth() + 1, today.getDate() + 1)
  }];
  testCases.forEach(testCase => {
    it(`should display correct styles for ${testCase.description}`, () => {
      console.log(testCase.isSelected);
      cy.mount(__ds_scope.IvuDayButtonComponent, {
        componentProperties: {
          day: testCase.date
        },
        providers: [__ds_scope.IvuDateTimePickerService]
      }).then(({
        fixture
      }) => {
        const service = fixture.componentRef.injector.get(__ds_scope.IvuDateTimePickerService);
        if (testCase.isSelected) {
          service.selectDate(testCase.date);
        }
        fixture.detectChanges();
      });

      // Validate text content
      cy.get('[data-testid="time"]').should('contain.text', testCase.date.getDate().toString());

      // Validate dynamic classes based on selection and day status
      if (testCase.isSelected && testCase.isToday) {
        cy.get('[data-testid="time"]').should('have.class', 'bg-secondary-500');
      } else if (testCase.isSelected && !testCase.isToday) {
        cy.get('[data-testid="time"]').should('have.class', 'bg-primary-500');
      }
      if (testCase.isToday && !testCase.isSelected) {
        cy.get('[data-testid="time"]').should('have.class', 'text-secondary-500');
      } else if (!testCase.isToday && !testCase.isSelected && testCase.isInCurrentMonth) {
        cy.get('[data-testid="time"]').should('not.have.class', 'text-gray-50');
        cy.get('[data-testid="time"]').should('not.have.class', 'text-secondary-500');
      } else if (!testCase.isToday && !testCase.isSelected && !testCase.isInCurrentMonth) {
        cy.get('[data-testid="time"]').should('have.class', 'text-gray-50');
      }
    });
  });
});
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/date-time-picker/components/day-picker/day-button/day-button.cy.ts", error: String((e && e.message) || e) }); }

