// uploads/error-page/providers/error-page-config.provider.ts
try { (() => {
const ERROR_PAGE_CONFIG = new InjectionToken('Error Page Config');

/**
 * Creates the providers used for the app error page
 *
 * @param {IvuErrorPageConfig} config - The error page config
 * @returns {any} {EnvironmentProviders} - the list of providers for the error page
 * @export
 */
function provideErrorPageConfig(config) {
  return makeEnvironmentProviders([{
    provide: ERROR_PAGE_CONFIG,
    useValue: config
  }]);
}

/**
 * Constructs the factory for providing error page config
 *
 * @param {FactorySansProvider} config - The error page config
 * @returns {any} {Provider} - the provider for the error page
 * @export
 */
function provideErrorPageConfigFactory(config) {
  return {
    provide: ERROR_PAGE_CONFIG,
    ...config
  };
}
Object.assign(__ds_scope, { ERROR_PAGE_CONFIG, provideErrorPageConfig, provideErrorPageConfigFactory });
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/error-page/providers/error-page-config.provider.ts", error: String((e && e.message) || e) }); }

