// uploads/interactive-icon/interactive-icon.component.cy.ts
try { (() => {
describe(__ds_scope.IvuInteractiveIconComponent.name, () => {
  let config;
  beforeEach(() => {
    config = {
      imports: [__ds_scope.IvuIconComponent, CommonModule],
      componentProperties: {
        icon: 'icon-close',
        iconSize: 'lg',
        color: 'error',
        disabled: false,
        focusable: true,
        clicked: createOutputSpy('clickSpy')
      }
    };
  });
  it('mounts', () => {
    cy.mount(__ds_scope.IvuInteractiveIconComponent, config);
  });
  it('should check if the appropriate icon is rendered', () => {
    cy.mount(__ds_scope.IvuInteractiveIconComponent, config);
    cy.dataTestId('ivuIconContainer').should('have.class', 'icon-close');
  });
  it(`should check if the interactive icon is rendered in appropriate color`, () => {
    cy.mount(__ds_scope.IvuInteractiveIconComponent, config);
    cy.get('ivu-icon').should('have.class', 'text-error-500');
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        color: 'primary'
      }
    });
    cy.get('ivu-icon').should('have.class', 'text-primary-500');
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        color: 'primary',
        selected: true
      }
    });
    cy.get('ivu-icon').should('have.class', 'text-secondary-500');
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        color: 'success'
      }
    });
    cy.get('ivu-icon').should('have.class', 'text-success-500');
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        color: 'white'
      }
    });
    cy.get('ivu-icon').should('have.class', 'text-ivu-white');
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        disabled: true
      }
    });
    cy.get('ivu-icon').should('have.class', 'text-gray-40');
  });
  it('should check if the button is enabled/disabled based on the value of disabled property passed', () => {
    cy.mount(__ds_scope.IvuInteractiveIconComponent, config);
    cy.dataTestId('ivuInteractiveIconBtn').should('be.enabled');
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        disabled: true
      }
    });
    cy.dataTestId('ivuInteractiveIconBtn').should('be.disabled');
  });
  it('should check if "cursor-not-allowed" class is added when interactive icon is disabled', () => {
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        disabled: true
      }
    });
    cy.dataTestId('ivuInteractiveIconBtn').should('have.class', 'cursor-not-allowed');
  });
  it('should check if clicked event is emitted on click of interactive icon button', () => {
    cy.mount(__ds_scope.IvuInteractiveIconComponent, config);
    cy.dataTestId('ivuInteractiveIconBtn').should('be.enabled').click();
    cy.get('@clickSpy').should('have.been.calledOnce');
  });
  it('should check if the size of icon is altered based on the iconSize property value', () => {
    cy.mount(__ds_scope.IvuInteractiveIconComponent, config);
    cy.dataTestId('ivuInteractiveIconBtn').should('have.class', 'h-8 w-8');
    cy.mount(__ds_scope.IvuInteractiveIconComponent, {
      ...config,
      componentProperties: {
        ...config.componentProperties,
        iconSize: 'sm'
      }
    });
    cy.dataTestId('ivuInteractiveIconBtn').should('have.class', 'h-6 w-6');
  });
});
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/interactive-icon/interactive-icon.component.cy.ts", error: String((e && e.message) || e) }); }

