/**
 * Gets the vehicle data.
 *
 * @returns {any} {VehicleMarker<unknown>}
 * @export
 */
function getVehicleData() {
  return {
    distance: 200,
    label: '-0.5',
    data: {
      deviation: {
        value: -0.5,
        prefix: '-',
        semantics: 'ON_TIME'
      }
    },
    currentPosition: 'NetPoint~IVU~9862~1',
    renderClass: {
      labelBgClass: 'fill-[rgb(221,246,193)]',
      labelClass: 'fill-[rgb(0,90,16)]',
      markerClass: 'fill-[rgb(153,236,60)] stroke-[rgb(118,184,40)]'
    }
  };
}

/**
 * Gets the link render config.
 *
 * @returns {any} {IvuItineraryNodeClass<unknown>[]}
 * @export
 */
function getLinkRenderConfig() {
  return [{
    className: 'stroke-primary-500 stroke-1',
    predicate: true
  }, {
    className: '[stroke-dasharray:1] stroke-red-500',
    predicate: node => !!node.metaAttribute?.includes('CANCELLED')
  }, {
    className: 'stroke-gray-40',
    predicate: node => !!node.metaAttribute?.includes('SERVED')
  }];
}

/**
 * Gets the node render config.
 *
 * @returns {any} {IvuItineraryNodeRenderConfig<unknown>}
 * @export
 */
function getNodeRenderConfig() {
  return {
    icon: node => {
      const data = node.data;
      if (node.metaAttribute?.includes('CANCELLED')) {
        return '\ue9f2';
      } else if (data?.identification?.netPoint?.type === 'DEPOT_POINT') {
        return '\uea03';
      } else if (data?.identification?.netPoint?.type === 'LINK_POINT') {
        return '\uea02';
      } else if (data?.identification?.netPoint?.type === 'BEACON_POINT') {
        return '\uea00';
      } else if (node.data?.demandStop) {
        return '\uea2a';
      } else {
        return '\ue942';
      }
    },
    classConfig: [{
      className: 'group-[.node-group.hovered]:fill-yellow-500 group-[.node-group.selected]:fill-cyan-800 group-[.node-group.pressed]:fill-lime-500',
      predicate: true
    }, {
      className: 'fill-green-500',
      predicate: node => !!node.metaAttribute?.includes('ACTIVE')
    }, {
      className: 'fill-red-500',
      predicate: node => !!node.metaAttribute?.includes('CANCELLED')
    }, {
      className: 'fill-blue-500',
      predicate: node => !!node.metaAttribute?.includes('SERVED')
    }]
  };
}
Object.assign(__ds_scope, { getItineraryDiagramDataSource, getVehicleData, getLinkRenderConfig, getNodeRenderConfig });
