// uploads/message-bar/models/message-ref.ts
try { (() => {
/**
 * Class representing the reference of a message bar.
 *
 * @class IvuMessageRef
 * @export
 */
class IvuMessageRef {
  /**
   * An observable, emits after the message bar is closed/dismissed.
   *
   * @memberof IvuMessageRef
   */
  afterDismiss$ = new Subject();

  /**
   * An observable, emits the action name as soon as action button is clicked on the message bar.
   *
   * @memberof IvuMessageRef
   */
  action$ = new Subject();

  /**
   * Creates an instance of IvuMessageRef.
   *
   * @memberof IvuMessageRef
   * @param {IvuMessageConfig} messageConfig Configuration object for the message bar.
   */
  constructor(messageConfig) {
    this.messageConfig = messageConfig;
  }

  /**
   * Method the removes the message bar.
   *
   * @memberof IvuMessageRef
   * @param {string} [action] Name of the message action.
   */
  removeMessage(action) {
    if (action) {
      this.action$.next(action);
    }
    this.afterDismiss$.next();
    this.action$.complete();
    this.afterDismiss$.complete();
  }
}
Object.assign(__ds_scope, { IvuMessageRef });
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/message-bar/models/message-ref.ts", error: String((e && e.message) || e) }); }

