// uploads/number-input/validators/number-input.validators.ts
try { (() => {
/**
 * Validator function to check the format of number input.
 *
 * @export
 * @param {('integer' | 'decimal')} type
 * @return {*}  {ValidatorFn}
 */
function invalidNumberFormat(type) {
  return control => {
    const value = control.value;
    if (!value) {
      return null;
    }
    if (isNumber(value) && type === 'integer' && !isInteger(value)) {
      return {
        invalid: true
      };
    }
    return null;
  };
}
Object.assign(__ds_scope, { invalidNumberFormat });
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/number-input/validators/number-input.validators.ts", error: String((e && e.message) || e) }); }

// uploads/overlay-panel/overlay-panel-settings.ts
try { (() => {
const marginBetweenPanelAndScreenEdges = 16;
const getOverlayPositions = offset => {
  const shiftOverlayToTop = {
    originX: 'center',
    originY: 'top',
    overlayX: 'center',
    overlayY: 'bottom',
    offsetY: -offset
  };
  const shiftOverlayToBottom = {
    originX: 'center',
    originY: 'bottom',
    overlayX: 'center',
    overlayY: 'top',
    offsetY: offset
  };

  // Shift overlay to the left if going out of the right viewport boundary
  const shiftOverlayToTopLeft = {
    originX: 'end',
    originY: 'top',
    overlayX: 'end',
    overlayY: 'bottom',
    offsetY: -offset
  };

  // Shift overlay to the right if going out of the left viewport boundary
  const shiftOverlayToTopRight = {
    originX: 'start',
    originY: 'top',
    overlayX: 'start',
    overlayY: 'bottom',
    offsetY: -offset
  };

  // Shift overlay to the left if going out of the right viewport boundary
  const shiftOverlayToBottomLeft = {
    originX: 'end',
    originY: 'bottom',
    overlayX: 'end',
    overlayY: 'top',
    offsetY: offset
  };

  // Shift overlay to the right if going out of the left viewport boundary
  const shiftOverlayToBottomRight = {
    originX: 'start',
    originY: 'bottom',
    overlayX: 'start',
    overlayY: 'top',
    offsetY: offset
  };
  const shiftOverlay = {
    top: [shiftOverlayToTop, shiftOverlayToTopLeft, shiftOverlayToTopRight],
    bottom: [shiftOverlayToBottom, shiftOverlayToBottomLeft, shiftOverlayToBottomRight],
    auto: [shiftOverlayToBottom, shiftOverlayToTop, shiftOverlayToTopLeft, shiftOverlayToTopRight, shiftOverlayToBottomLeft, shiftOverlayToBottomRight]
  };
  return shiftOverlay;
};
Object.assign(__ds_scope, { marginBetweenPanelAndScreenEdges, getOverlayPositions });
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/overlay-panel/overlay-panel-settings.ts", error: String((e && e.message) || e) }); }

