      cy.get('@highlightedText').eq(0).find('span.font-bold').should('have.text', 'As');
      cy.get('@highlightedText').eq(0).find('span.font-bold + span').should('have.text', 'ely');
      cy.get('@highlightedText').eq(1).find('span.font-bold').should('have.text', 'As');
      cy.get('@highlightedText').eq(1).find('span.font-bold + span').should('have.text', 'sunta');
      cy.get('@highlightedText').eq(2).find('span.font-bold').should('have.text', 'as');
      cy.get('@highlightedText').eq(2).find('span:not(.font-bold)').eq(0).should('have.text', 'Pl');
      cy.get('@highlightedText').eq(2).find('span:not(.font-bold)').eq(1).should('have.text', 'sey');
      cy.get('@highlightedText').eq(3).find('span.font-bold').should('have.text', 'as');
      cy.get('@highlightedText').eq(3).find('span:not(.font-bold)').eq(0).should('have.text', 'R');
      cy.get('@highlightedText').eq(3).find('span:not(.font-bold)').eq(1).should('have.text', 'putin');
      cy.get('@highlightedText').eq(4).find('span.font-bold').should('have.text', 'as');
      cy.get('@highlightedText').eq(4).find('span:not(.font-bold)').eq(0).should('have.text', 'M');
