try { (() => {
// Injection token for providing default spinner configuration
const IVU_SPINNER_CONFIG = new InjectionToken('IVU_SPINNER_CONFIG', {
  providedIn: 'root',
  factory: () => ({
    type: 'ivu'
  })
});

// Function to provide custom spinner configuration
function provideSpinnerConfig(config) {
  return makeEnvironmentProviders([{
    provide: IVU_SPINNER_CONFIG,
    useValue: config
  }]);
}
Object.assign(__ds_scope, { IVU_SPINNER_CONFIG, provideSpinnerConfig });
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/spinner/providers/token-provider.ts", error: String((e && e.message) || e) }); }

