// uploads/tabs/tab-nav/tab-nav.component.cy.ts
try { (() => {
function getSampleTabs() {
  return [{
    id: '1',
    title: 'Tab 1',
    icon: 'icon-detour'
  }, {
    id: '2',
    title: 'Tab 2',
    icon: 'icon-help'
  }, {
    id: '3',
    title: 'Tab 3',
    icon: 'icon-call'
  }];
}
describe('IvuTabNavComponent', () => {
  const buttons = getSampleTabs();
  const activeButtonId = signal(buttons[0].id);
  beforeEach(() => {
    cy.mount(`
            <ivu-tab-nav size="default">
                @for (button of buttons; track button.id; let first = $first; let last = $last){
                    <button ivuTabHeaderItem [title]="button.title"
                        [icon]="button.icon" [active]="activeButtonId() === button.id" [attr.data-tabid]="button.id"
                        (click)="onButtonClick(button)">
                    </button>
                }
            </ivu-tab-nav>
            `, {
      imports: [__ds_scope.IvuTabNavComponent, __ds_scope.IvuTabHeaderItemComponent, CommonModule],
      componentProperties: {
        buttons,
        activeButtonId,
        onButtonClick: button => {
          activeButtonId.set(button.id);
        }
      }
    });
  });
  it('should mount successfully', () => {
    cy.get('ivu-tab-nav').should('exist');
  });
  it(`should shift focus following keyboard movements`, () => {
    cy.get('[data-tabid="1"]').as('firstButton');
    cy.get('[data-tabid="2"]').as('secondButton');
    cy.get('[data-tabid="3"]').as('thirdButton');
    // click on first button to get focus on it
    cy.get('@firstButton').click();
    cy.get('@firstButton').should('have.css', 'outline-color', 'rgb(1, 81, 140)');
    cy.get('@secondButton').should('not.have.css', 'outline-color', 'rgb(1, 81, 140)');
    cy.get('@thirdButton').should('not.have.css', 'outline-color', 'rgb(1, 81, 140)');
    // press right arrow
    cy.dataTestId('tabNavContainer').trigger('keydown', {
      key: 'ArrowRight',
      code: 'ArrowRight',
      keyCode: 39,
      which: 39,
      bubbles: true
    });
    cy.get('@firstButton').should('not.have.css', 'outline-color', 'rgb(1, 81, 140)');
    cy.get('@secondButton').should('have.css', 'outline-color', 'rgb(1, 81, 140)');
    cy.get('@thirdButton').should('not.have.css', 'outline-color', 'rgb(1, 81, 140)');
    // press right arrow again
    cy.dataTestId('tabNavContainer').trigger('keydown', {
      key: 'ArrowRight',
      code: 'ArrowRight',
      keyCode: 39,
      which: 39,
      bubbles: true
    });
    cy.get('@firstButton').should('not.have.css', 'outline-color', 'rgb(1, 81, 140)');
    cy.get('@secondButton').should('not.have.css', 'outline-color', 'rgb(1, 81, 140)');
    cy.get('@thirdButton').should('have.css', 'outline-color', 'rgb(1, 81, 140)');
  });
  it(`should activate the button when ENTER is pressed`, () => {
    cy.get('[data-tabid="1"]').as('firstButton');
    cy.get('[data-tabid="2"]').as('secondButton');
    cy.get('[data-tabid="3"]').as('thirdButton');
    // click on first button to get focus on it
    cy.get('@firstButton').click();
    cy.get('@firstButton').findDataTestId('activeIndicator').should('exist');
    cy.get('@secondButton').findDataTestId('activeIndicator').should('not.exist');
    cy.get('@thirdButton').findDataTestId('activeIndicator').should('not.exist');
    // press right arrow and press ENTER
    cy.dataTestId('tabNavContainer').trigger('keydown', {
      key: 'ArrowRight',
      code: 'ArrowRight',
      keyCode: 39,
      which: 39,
      bubbles: true
    });
    cy.focused().type('{enter}');
    cy.get('@firstButton').findDataTestId('activeIndicator').should('not.exist');
    cy.get('@secondButton').findDataTestId('activeIndicator').should('exist');
    cy.get('@thirdButton').findDataTestId('activeIndicator').should('not.exist');
  });
});
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/tabs/tab-nav/tab-nav.component.cy.ts", error: String((e && e.message) || e) }); }

