// uploads/time-input/validators/time-input-form-validators.ts
try { (() => {
function invalidFormatValidator(timeString) {
  return () => {
    if (timeString === '') {
      return null;
    }
    const timeFormatRegex = /^(\d{4}|\d{2}:\d{2})$/;
    if (!timeFormatRegex.test(timeString)) {
      return {
        invalidTimeFormat: true
      };
    }
    return null;
  };
}
function invalidTimeValidator(timeString, amPM) {
  return () => {
    if (timeString === '') {
      return null;
    }
    if (!isValidTime(timeString, amPM)) {
      return {
        invalidTime: true
      };
    }
    return null;
  };
}
function isValidTime(timeString, amPM) {
  const stringWithoutSuffix = timeString.replace(':', '');
  const hours = parseInt(stringWithoutSuffix.slice(0, 2), 10);
  const minutes = parseInt(stringWithoutSuffix.slice(2, 4), 10);
  return !(hours === 0 && amPM || hours > 23 || minutes > 59 || amPM && hours > 12);
}
Object.assign(__ds_scope, { invalidFormatValidator, invalidTimeValidator, isValidTime });
})(); } catch (e) { __ds_ns.__errors.push({ path: "uploads/time-input/validators/time-input-form-validators.ts", error: String((e && e.message) || e) }); }

