/**
 * Class representing the reference of the toast.
 *
 * @class IvuToastRef
 * @export
 */
class IvuToastRef {
  /**
   * An observable that emits after the toast is closed/dismissed.
   *
   * @memberof IvuToastRef
   */
  afterDismissed$ = new Subject();
  /**
   * An observable that emits when the dismissal of toast starts.
   *
   * @memberof IvuToastRef
   */
  beforeDismiss$ = new Subject();
  /**
   * Property to determine the reason for toast dismissal.
   *
   * @private
   * @memberof IvuToastRef
   */
  dismissReason = '';

  /**
   * Method responsible for dismissing the toast.
   *
   * @memberof IvuToastRef
   */
  dismiss() {
    this.beforeDismiss$.next();
    this.beforeDismiss$.complete();
  }

  /**
   * Method responsible for dismissing the toast with an action.
   *
   * @memberof IvuToastRef
   * @param {string} action
   */
  dismissWithAction(action) {
    this.dismissReason = action;
    this.dismiss();
  }

  /**
   * Method responsible for finishing the toast dismissal.
   *
   * @memberof IvuToastRef
   */
  _finishDismiss() {
    this.afterDismissed$.next(this.dismissReason || 'dismiss');
    this.afterDismissed$.complete();
  }
}
Object.assign(__ds_scope, { IvuToastRef });
